:root {

    --color-bg-primary: #1a1a2e; 
    --color-text-dark: #d9d9d9; 
    --color-text-primary: #ffffff; 
    --color-accent: #ff6b6b; 
    --color-secondary: #4ecdc4; 
    --color-success: #7ed87e; 


    --font: 'Press Start 2P', system-ui, -apple-system, Roboto, monospace; 
    --border-radius: 4px; 
    --shadow-base: 3px 3px 0 var(--color-accent); 


    --space-xs: 4px;
    --space-sm: 8px;
    --space-md: 16px;
    --space-lg: 32px;
    --space-xl: 64px;


    --transition-speed: 0.2s;
}
*, *::before, *::after {
    box-sizing: border-box;
}
body {
    margin: 0;
    padding: 0;
    background-color: var(--color-bg-primary);
    color: var(--color-text-dark);
    font-family: var(--font);
    line-height: 1.6;
}
h1, h2, h3 {
    margin-top: 0;
    margin-bottom: var(--space-md);
    line-height: 1.2;
    color: var(--color-text-primary);

    text-shadow: 2px 2px 0 rgba(0, 0, 0, 0.3);
}
h1 { font-size: 2rem; }
h2 { font-size: 1.75rem; border-bottom: var(--space-xs) solid var(--color-secondary); padding-bottom: var(--space-sm); }
h3 { font-size: 1.4rem; color: var(--color-accent); }
p {
    margin-bottom: var(--space-md);
}
a {
    color: var(--color-secondary);
    text-decoration: none;
    transition: color var(--transition-speed) ease, background-color var(--transition-speed) ease;
    cursor: pointer;
}
a:hover {
    color: var(--color-accent);
    text-decoration: underline;
}
.container {
    max-width: 1200px; 
    margin: 0 auto;
    padding: 0 var(--space-lg);
}
.btn {
    display: inline-block;
    padding: var(--space-sm) var(--space-md);
    background-color: var(--color-accent);
    color: var(--color-text-primary);
    border: none;
    cursor: pointer;
    font-family: inherit;
    font-size: 1rem;

    box-shadow: var(--shadow-base);
    transition: all var(--transition-speed) ease;
    text-transform: uppercase;
}
.btn:hover {
    background-color: #ff8c8c; 
    box-shadow: 1px 1px 0 rgba(0, 0, 0, 0.3); 
    transform: translate(2px, 2px);
}
.btn:disabled {
    background-color: #555;
    cursor: not-allowed;
    box-shadow: none;
    transform: none;
}

