const MAX_LEVELS = 5;

// Estructura de datos para los niveles (Mapa, dimensiones, estado inicial)
const levelsData = [
    {
        level: 1,
        mapWidth: 8,
        mapHeight: 6,
        initialMoves: 20,
        cajasPendientes: 5,
        // Mapa de ejemplo: S=Suelo, P=Pared, A=Avatar inicial, O=Objetivo/Meta, C=Caja
        mapLayout: [
            ['P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'],
